<?php
namespace Tests\Feature;
use App\Models\{Building,Campus,Floor,FloorPlan,Institution,User};use Database\Seeders\RolesAndPermissionsSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\Storage;use Tests\TestCase;
class FloorPlanCalibrationTest extends TestCase {use RefreshDatabase;protected function setUp():void{parent::setUp();$this->seed(RolesAndPermissionsSeeder::class);}private function floor():Floor{$i=Institution::create(['name'=>'Test','slug'=>'test']);$c=$i->campuses()->create(['name'=>'Main','code'=>'MAIN']);$b=$c->buildings()->create(['name'=>'Library','code'=>'LIB']);return $b->floors()->create(['name'=>'Ground','code'=>'G','level_number'=>0]);}public function test_admin_can_upload_floor_plan():void{Storage::fake('local');$u=User::factory()->create();$u->assignRole('Network Admin');$f=$this->floor();$this->actingAs($u)->postJson("/api/floors/{$f->id}/floor-plans",['floor_plan'=>UploadedFile::fake()->image('plan.png',1000,800)])->assertCreated()->assertJson(['version'=>1,'is_active'=>true]);$this->assertDatabaseHas('floor_plans',['floor_id'=>$f->id,'original_width'=>1000]);}public function test_calibration_calculates_pixels_per_metre():void{$u=User::factory()->create();$u->assignRole('Network Admin');$f=$this->floor();$p=$f->floorPlans()->create(['uploaded_by'=>$u->id,'original_name'=>'p.png','file_path'=>'x','mime_type'=>'image/png','file_size'=>1,'original_width'=>1000,'original_height'=>800,'version'=>1]);$this->actingAs($u)->patchJson("/api/floor-plans/{$p->id}/calibrate",['x1'=>0.1,'y1'=>0.5,'x2'=>0.6,'y2'=>0.5,'distance_metres'=>10])->assertOk()->assertJsonPath('pixels_per_metre','50.0000');}public function test_viewer_cannot_upload_floor_plan():void{$u=User::factory()->create();$u->assignRole('Viewer');$f=$this->floor();$this->actingAs($u)->postJson("/api/floors/{$f->id}/floor-plans",[])->assertForbidden();}}
